from rich.console import Console

def test_tty_compatible():
    # Test without TTY_COMPATIBLE
    os.environ.pop("TTY_COMPATIBLE", None)
    os.environ.pop("FORCE_COLOR", None)

    # We need to mock the file to not be a TTY
    class MockFile:
        def isatty(self):
            return False
        def write(self, data):
            pass
        def flush(self):
            pass

    console = Console(file=MockFile())
    print(f"Without TTY_COMPATIBLE: {console.is_terminal()}")
    assert console.is_terminal() is False

    # Test with TTY_COMPATIBLE
    os.environ["TTY_COMPATIBLE"] = "1"
    console = Console(file=MockFile())
    print(f"With TTY_COMPATIBLE: {console.is_terminal()}")
    assert console.is_terminal() is True
    os.environ.pop("TTY_COMPATIBLE", None)

if __name__ == "__main__":
    try:
        test_tty_compatible()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
", "filepath": "/tmp/test_tty_compatible.py"}

